/**
 * dsh-lan-proxy — 存量 config.json 一次性迁移。
 *
 * rename-first marker，幂等：先把 config.json 原子改名为 config.json.migrated.bak
 * （存在即「已处理过」），再 sanitize 过滤后经 owner scope.update（Descriptor 面
 * 新 update：scope.update(patch, expectedRevision?)；条目 id 见 SETTINGS_NS）增量
 * 写入官方 settings 存储；中断态（.bak 存在且 config.json 不存在）从 bak 重放。
 * 本域只拥有「旧文件长什么样」这份知识，净化规则与写面都取自配置域。
 */
import { existsSync, readFileSync, renameSync, unlinkSync } from "node:fs";
import { join } from "node:path";
import { errorMessage } from "../../../../../../../shared/host-utils.js";
import { sanitizeSettings, normalizeLegacyWsCompressPaths } from "../../../config/interface.ts";
import type { OwnerScopeLike } from "../../../config/interface.ts";

/** 迁移备份文件名（同时是幂等标记：存在即「已处理过」）。 */
export const MIGRATED_BAK_NAME = "config.json.migrated.bak";

/**
 * 迁移写入前的最后一收口（issue #395 M2）：sanitize 后再对 wsCompressPaths 应用
 * 旧白名单归一化——显式保存过旧默认 ["/api/events.mux", "/api/events.host"] 的
 * 存量 config.json 迁移后同样写入新默认 ["/api/remote.mux"]；自定义白名单原样保留。
 */
function normalizeMigratedWsCompressPaths(
  sanitized: ReturnType<typeof sanitizeSettings>,
): ReturnType<typeof sanitizeSettings> {
  if (sanitized === null || sanitized.wsCompressPaths === undefined) return sanitized;
  const normalized = normalizeLegacyWsCompressPaths(sanitized.wsCompressPaths);
  if (normalized === undefined) return sanitized;
  return { ...sanitized, wsCompressPaths: [...normalized] };
}

/** migrateFileConfig 的结果（导出供单测断言）。 */
export interface MigrationOutcome {
  /** 本次是否执行了改名标记（false = config.json 不存在，或仅从中断态重放）。 */
  performed: boolean;
  /** 是否有有效键写入了 owner scope（含中断态重放成功）。 */
  migrated: boolean;
  /** 写入失败后是否已回滚改名（config.json 已还原）。 */
  rolledBack: boolean;
  /** 损坏/空 JSON：仅改名标记、不写入（防固化 schema 默认值）。 */
  skippedCorrupt: boolean;
  /** 本次是否为中断态重放（.bak 存在且 config.json 不存在）。 */
  resumed: boolean;
}

/**
 * 中断态重放：上次「改名成功 → scope.update 完成前」进程被杀的现场是
 * `.bak` 存在且 `config.json` 不存在——此时不能按幂等跳过（否则配置永滞
 * .bak 且无提示），视为未完成迁移，从 bak 重放「解析→sanitize→scope.update」。
 * 成功后保留 bak（update 同值 merge 幂等，后续启动重放无害）；损坏/无效/
 * 写入失败则 warn 明示手动恢复路径。
 */
async function resumeMigrateFromBak(
  bakPath: string,
  scope: Pick<OwnerScopeLike, "update">,
  logger?: { warn?: (...a: unknown[]) => void },
): Promise<MigrationOutcome> {
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(bakPath, "utf8"));
  } catch {
    logger?.warn?.(
      `lan-proxy: 检测到上次未完成的迁移残留 ${MIGRATED_BAK_NAME}，但文件不是合法 JSON — 无法自动恢复，请手动检查该文件（原始 config.json 内容应在其内）或删除它`,
    );
    return {
      performed: false,
      migrated: false,
      rolledBack: false,
      skippedCorrupt: true,
      resumed: true,
    };
  }
  const sanitized0 =
    typeof parsed === "object" && parsed !== null ? sanitizeSettings(parsed) : null;
  if (sanitized0 === null || Object.keys(sanitized0).length === 0) {
    logger?.warn?.(
      `lan-proxy: 上次未完成的迁移残留 ${MIGRATED_BAK_NAME} 无可迁移的有效键 — 已跳过，确认无误后可手动删除该文件`,
    );
    return {
      performed: false,
      migrated: false,
      rolledBack: false,
      skippedCorrupt: true,
      resumed: true,
    };
  }
  const sanitized = normalizeMigratedWsCompressPaths(sanitized0);
  try {
    await scope.update(sanitized as Record<string, unknown>);
    logger?.warn?.(
      `lan-proxy: 检测到上次未完成的迁移 — 已从 ${MIGRATED_BAK_NAME} 重放写入设置；确认运行正常后可手动删除该备份`,
    );
    return {
      performed: false,
      migrated: true,
      rolledBack: false,
      skippedCorrupt: false,
      resumed: true,
    };
  } catch (err) {
    logger?.warn?.(
      `lan-proxy: 未完成的迁移从 ${MIGRATED_BAK_NAME} 重放写入设置失败（${errorMessage(err)}）— 配置仍保留在该备份中，请排查后重启重试，或手动将其内容恢复到设置`,
    );
    return {
      performed: false,
      migrated: false,
      rolledBack: false,
      skippedCorrupt: false,
      resumed: true,
    };
  }
}

/**
 * 缺失态分流（migrateFileConfig 步骤 0-1）：config.json 不存在时决定幂等或重放。
 * 返回 outcome 表示已定论（调用方直接返回），undefined 表示存在 config.json、需继续改名迁移。
 */
async function handleMissingMigratedConfig(
  cfgPath: string,
  bakPath: string,
  scope: Pick<OwnerScopeLike, "update">,
  logger?: { warn?: (...a: unknown[]) => void },
): Promise<MigrationOutcome | undefined> {
  // 中断态优先于幂等判定：config.json 与 .bak 同时不存在才是真正的已迁移稳态。
  if (!existsSync(cfgPath)) {
    if (existsSync(bakPath)) return resumeMigrateFromBak(bakPath, scope, logger);
    return {
      performed: false,
      migrated: false,
      rolledBack: false,
      skippedCorrupt: false,
      resumed: false,
    };
  }
  return undefined;
}

/**
 * 读 bak 并解析 JSON（migrateFileConfig 步骤 3 前半）。
 * 成功返回解析值；损坏时按原口径 warn 并返回 undefined（调用方映射为已标记 corrupt）。
 */
function readMigratedBakJson(
  bakPath: string,
  logger?: { warn?: (...a: unknown[]) => void },
): unknown | undefined {
  try {
    return JSON.parse(readFileSync(bakPath, "utf8"));
  } catch {
    logger?.warn?.(
      `lan-proxy: 存量 config.json 不是合法 JSON — 仅标记为已迁移（${MIGRATED_BAK_NAME}），不写入设置`,
    );
    return undefined;
  }
}

/**
 * 净化已解析的 bak 内容（migrateFileConfig 步骤 3 后半 + 步骤 4 前半）。
 * 非对象 / 含非法值时按原口径 warn 并返回 null；空对象返回 null（原口径无 warn）；
 * 成功返回归一化后的 sanitized（复用 normalizeMigratedWsCompressPaths）。
 */
function sanitizeMigratedParsed(
  parsed: unknown,
  logger?: { warn?: (...a: unknown[]) => void },
): Exclude<ReturnType<typeof sanitizeSettings>, null> | null {
  if (typeof parsed !== "object" || parsed === null) {
    logger?.warn?.(
      `lan-proxy: 存量 config.json 不是配置对象 — 仅标记为已迁移（${MIGRATED_BAK_NAME}），不写入设置`,
    );
    return null;
  }
  const sanitized0 = sanitizeSettings(parsed);
  if (sanitized0 === null) {
    // 含类型非法值：整体不写入（与保存通道同口径，宁可不迁也不迁一半）。
    logger?.warn?.(
      `lan-proxy: 存量 config.json 含非法配置值 — 仅标记为已迁移（${MIGRATED_BAK_NAME}），不写入设置`,
    );
    return null;
  }
  if (Object.keys(sanitized0).length === 0) {
    return null;
  }
  return normalizeMigratedWsCompressPaths(sanitized0) as Exclude<
    ReturnType<typeof sanitizeSettings>,
    null
  >;
}

/** 已标记 corrupt 的统一返回（migrateFileConfig 步骤 3 的三种损坏形态共用）。 */
function migratedCorruptOutcome(): MigrationOutcome {
  return {
    performed: true,
    migrated: false,
    rolledBack: false,
    skippedCorrupt: true,
    resumed: false,
  };
}

/**
 * 回滚改名并落日志（migrateFileConfig 步骤 5）。
 * 数据始终存在于 config.json 或 bak 之一；回滚失败时按原口径先报回滚失败、再报写入失败。
 */
function rollbackMigratedRename(
  cfgPath: string,
  bakPath: string,
  logger: { warn?: (...a: unknown[]) => void } | undefined,
  err: unknown,
): void {
  try {
    if (!existsSync(cfgPath)) renameSync(bakPath, cfgPath);
  } catch (rollbackErr) {
    logger?.warn?.(
      `lan-proxy: 迁移回滚失败（${errorMessage(rollbackErr)}）— 数据保留在 ${MIGRATED_BAK_NAME}，请手动恢复`,
    );
  }
  logger?.warn?.(
    `lan-proxy: 存量 config.json 迁移写入设置失败（${errorMessage(err)}）— 已回滚，下次启动重试`,
  );
}

/**
 * 存量 config.json 一次性迁移到官方 settings 命名空间（rename-first marker）。
 *
 * 时序（issue #110 修订路线）：
 * 0. 中断态（`.bak` 存在且 `config.json` 不存在，即上次改名后写入未完成）→
 *    从 bak 重放写入（见 resumeMigrateFromBak），不静默跳过；
 * 1. `config.json` 不存在（且无中断态残留）→ 直接返回（幂等：二次启动跳过）；
 * 2. 先原子改名 `config.json` → `config.json.migrated.bak`（POSIX rename 原子；
 *    Windows 目标已存在会抛错，故先 unlink 旧 bak——bak 仅是保险副本，被新的
 *    用户手动恢复内容取代可接受）；改名成功即视为「已处理」，无论后续成败；
 * 3. 解析 bak：损坏/非对象/无有效键 → 到此为止（只标记不写入，避免把 schema
 *    默认值固化进用户层、压制后续默认值演进）；
 * 4. sanitizeSettings 过滤后经新 update 写面增量写入（owner scope.update：只写文件里
 *    显式存在的键，schema 默认保持动态兜底——spike 结论优先 update，replace 仅当
 *    需要整节割接时使用；dsh 0.1.7-rc.1 引入、rc.2 沿用的同语义由条目 id 寻址，签名见 OwnerScopeLike）；
 * 5. 写入失败 → 回滚改名（bak 还原为 config.json）并 warn，下次启动重试。
 *
 * 必须在 settings 服务 attach 后调用（installLanProxySettings 的 onScope 内），
 * 且先于任何 enabled 早退——禁用用户跨版本升级同样要完成迁移。
 */
export async function migrateFileConfig(
  configDir: string,
  scope: Pick<OwnerScopeLike, "update">,
  logger?: { warn?: (...a: unknown[]) => void },
): Promise<MigrationOutcome> {
  const cfgPath = join(configDir, "config.json");
  const bakPath = join(configDir, MIGRATED_BAK_NAME);
  const missing = await handleMissingMigratedConfig(cfgPath, bakPath, scope, logger);
  if (missing !== undefined) return missing;
  // Windows 上 rename 到已存在目标会抛错；先移除历史 bak（见函数注释）。
  if (existsSync(bakPath)) unlinkSync(bakPath);
  renameSync(cfgPath, bakPath);
  const parsed = readMigratedBakJson(bakPath, logger);
  if (parsed === undefined) return migratedCorruptOutcome();
  const sanitized = sanitizeMigratedParsed(parsed, logger);
  if (sanitized === null) return migratedCorruptOutcome();
  try {
    await scope.update(sanitized as Record<string, unknown>);
    return {
      performed: true,
      migrated: true,
      rolledBack: false,
      skippedCorrupt: false,
      resumed: false,
    };
  } catch (err) {
    // 写入失败：回滚改名，让下次启动重试（数据始终存在于 config.json 或 bak 之一）。
    rollbackMigratedRename(cfgPath, bakPath, logger, err);
    return {
      performed: true,
      migrated: false,
      rolledBack: true,
      skippedCorrupt: false,
      resumed: false,
    };
  }
}

/**
 * dsh-lan-proxy — 旧扁平目录一次性迁出（issue #911）。
 *
 * 把 lan-proxy/（#911 前自签证书缓存所在）收进包私有目录
 * @wingsky-1/dsh-lan-proxy/，对标 notifier upgrade/storage-layout 那一步
 * （旧文件搬运 + 目标已存在不覆盖 + 旧文件归档留证据）。
 *
 * 语义：
 * - 目标已存在即视为处理过：不覆盖（用户可能已在新位置换过证书），只把
 *   旧文件归档为 .migrated.bak（与 migrateFileConfig 的 marker 同族）；
 * - 目标缺失且旧文件存在：原子改名搬运；
 * - 两边都没有：全新安装（ensureSelfSignedTls 随后在新目录建出），零操作；
 * - 幂等：搬完/归档完重跑不累积。
 *
 * 失败口径：单文件搬不动记 warn；若出现搬运失败则把已搬的回滚（改名回去，
 * best effort），并回落旧目录——调用方本轮全程只用一个目录（不双源），下次
 * 启动重跑本次迁移（参考 migrateFileConfig 的 rolledBack 语义）。
 */
import { existsSync, mkdirSync, renameSync } from "node:fs";
import { join } from "node:path";
import { legacyPluginDir, pluginDir } from "../../../shared/interface.ts";

/** 旧文件归档后缀（与 MIGRATED_BAK_NAME 同族的处理过标记）。 */
export const LEGACY_BAK_SUFFIX = ".migrated.bak";

/** resolvePluginDir 入参（文件名由调用方传入：自签 key/cert 名归 tls 域，config.json 名归本域）。 */
export interface LayoutMigrateOptions {
  /** 随目录迁移的文件名（含分隔符的一律跳过，防路径穿越）。 */
  files: readonly string[];
  /** 服务端日志兜底（失败只记日志，由返回值告知调用方降级）。 */
  logger?: { warn?: (...args: unknown[]) => void };
}

/** resolvePluginDir 结果。 */
export interface LayoutMigrateOutcome {
  /** 本轮生效目录（新旧二选一；调用方全程只用它）。 */
  dir: string;
  /** 本次实际搬运的文件名。 */
  moved: string[];
  /** 是否回落旧目录（搬运失败且已回滚）。 */
  fallback: boolean;
}

/** 反斜杠码点（写成码点比较，避免转义层吞反斜杠字面量）。 */
const BACKSLASH = 92;

/** 文件名合法性（防路径穿越：调用方传的应是常量，此处为最后一道防线）。 */
function isSafeName(name: string): boolean {
  if (name === "" || name === "." || name === "..") return false;
  for (const ch of name) {
    if (ch === "/" || ch.charCodeAt(0) === BACKSLASH) return false;
  }
  return true;
}

/** 取错误消息（日志用，不进响应）。 */
function errMsg(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

/**
 * 旧目录迁出并抉择本轮生效目录（同步；装配期最先跑，先于 prepareTls 与
 * migrateFileConfig——两者都读写本返回值目录）。
 */
export function resolvePluginDir(options: LayoutMigrateOptions): LayoutMigrateOutcome {
  const from = legacyPluginDir();
  const to = pluginDir();
  mkdirSync(to, { recursive: true });
  if (!existsSync(from)) return { dir: to, moved: [], fallback: false };
  const moved: string[] = [];
  const rollback: string[] = [];
  const warn = (message: string) => options.logger?.warn?.(message);
  for (const name of options.files) {
    if (!isSafeName(name)) continue;
    const src = join(from, name);
    const dst = join(to, name);
    if (!existsSync(src)) continue;
    if (existsSync(dst)) {
      try {
        renameSync(src, src + LEGACY_BAK_SUFFIX);
      } catch (err) {
        warn("lan-proxy: 旧目录文件 " + name + " 归档失败（保留原位）— " + errMsg(err));
      }
      continue;
    }
    try {
      renameSync(src, dst);
      moved.push(name);
      rollback.push(name);
    } catch (err) {
      warn("lan-proxy: 旧目录迁移 " + name + " 失败 — " + errMsg(err) + "，回滚并回落旧目录");
      for (const done of [...rollback].reverse()) {
        try {
          renameSync(join(to, done), join(from, done));
        } catch {
          // 回滚 best effort：残留即下次重跑，本轮仍回落旧目录（单目录抉择）。
        }
      }
      return { dir: from, moved: [], fallback: true };
    }
  }
  return { dir: to, moved, fallback: false };
}

/**
 * dsh-lan-proxy — 旧官方 settings section 到 canonical settings 的窄 facade。
 *
 * 通用文档读取、imported < live、JSON clone/cycle 防护、currentUser 优先与 marker 时序统一走
 * shared/legacy-settings-migration；本域只保留 LAN 的 namespace、配置 sanitizer 与默认路径。
 */
import { dshHome } from "../../../../../../../shared/dsh-home.js";
import {
  migrateLegacySettings as migrateSharedLegacySettings,
  readLegacySettings as readSharedLegacySettings,
} from "../../../../../../../shared/legacy-settings-migration.js";
import type {
  LegacySettingsMigrationOutcome,
  LegacySettingsMigrationStatus,
  LegacySettingsReadResult,
} from "../../../../../../../shared/legacy-settings-migration.js";
import { sanitizeSettings } from "../../../config/interface.ts";
import type { OwnerScopeLike } from "../../../config/interface.ts";
import { pluginDir } from "../../../shared/interface.ts";

/** 旧官方 settings namespace（只在本迁移子域出现）。 */
export const LEGACY_SETTINGS_NS = "dsh-lan-proxy";

/** settings 迁移自己的完成 marker；刻意不叫 config.json.migrated.bak。 */
export const SETTINGS_MIGRATION_MARKER_NAME = "settings.migrated";

/** marker 内容版本；成功写入后未来实现可据此演进而不误读旧 marker。 */
export const SETTINGS_MIGRATION_MARKER_VERSION = "1";

export type {
  LegacySettingsMigrationOutcome,
  LegacySettingsMigrationStatus,
  LegacySettingsReadResult,
};

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

/** LAN 特有校验：通用 validator 会把非数组对象形态的 wsDeflatePolicy 放行，迁移仍只收 plain record。 */
function sanitizeLegacySection(section: Record<string, unknown>): Record<string, unknown> | null {
  const sanitized = sanitizeSettings(section);
  if (sanitized === null) return null;
  const policy = (sanitized as Record<string, unknown>).wsDeflatePolicy;
  if (policy !== undefined && !isPlainRecord(policy)) return null;
  return sanitized as Record<string, unknown>;
}

/**
 * 读取两个 profile 文档并按 imported < settings.yaml 合并旧 section。
 * 任一存在文件读/解析失败即整体失败；不存在文件不算失败。
 */
export function readLegacySettings(
  options: { readonly home?: string } = {},
): LegacySettingsReadResult {
  return readSharedLegacySettings({
    legacyNamespace: LEGACY_SETTINGS_NS,
    home: options.home ?? dshHome(),
    sanitize: sanitizeLegacySection,
  });
}

export interface LegacySettingsMigrationOptions {
  /** profile home；默认取 dshHome()，测试/隔离 profile 可显式传入。 */
  readonly home?: string;
  /** 插件私有目录；marker 写在此处，默认取 pluginDir()。 */
  readonly configDir?: string;
  /** canonical settings 的 raw user section；字段存在即用户已决定。 */
  readonly currentUser?: unknown;
  /** canonical descriptor revision；用于 CAS 写入。 */
  readonly expectedRevision?: number;
  /** canonical owner scope；本 step 只使用 update，不触碰 config file state。 */
  readonly scope: Pick<OwnerScopeLike, "update">;
  readonly logger?: { warn?: (...args: unknown[]) => void };
}

/**
 * 执行一次旧 settings section 迁移。marker 命中后不读旧源、不写 scope。
 */
export async function migrateLegacySettings(
  options: LegacySettingsMigrationOptions,
): Promise<LegacySettingsMigrationOutcome> {
  return migrateSharedLegacySettings({
    legacyNamespace: LEGACY_SETTINGS_NS,
    home: options.home ?? dshHome(),
    configDir: options.configDir ?? pluginDir(),
    markerName: SETTINGS_MIGRATION_MARKER_NAME,
    markerVersion: SETTINGS_MIGRATION_MARKER_VERSION,
    sanitize: sanitizeLegacySection,
    currentUser: options.currentUser,
    expectedRevision: options.expectedRevision,
    scope: options.scope,
    logger: options.logger,
    label: "lan-proxy",
  });
}

