  it("normalizeConfig 入口点烟测试（空输入补默认 + 显式值透传）", () => {
    expect(normalizeConfig({ port: 1 }).port).toBe(1);
    expect(normalizeConfig({ port: 1 }).enabled).toBe(true);
  });
});
// ===== apply 内 readUser 真实闭包（CRAP 56/7 未覆盖 → 覆盖后 7） =====
