    const ops: string[] = [];
    let calls = 0;
    const flakyFs = {
      renameSync: (from: string, to: string) => {
        calls += 1;
        ops.push("rename:" + basename(from) + "->" + basename(to));
        if (calls === 4) throw new Error("staged rename failure");
        renameSync(from, to);
      },
      readdirSync,
      unlinkSync: (path: string) => {
